def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    reqs = [WATER_REQ]
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    total_req = sum(reqs)
    scarcity = float(supply) / float(total_req) if total_req > 0 else 1.0

    guaranteed_units = int(float(supply) // WATER_REQ)
    likely_competitors = len(alive_opponents) + 1
    very_tight = guaranteed_units < likely_competitors

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    critical = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1
    late_game = day >= 8
    high_supply = float(supply) >= 23.0

    if not alive_opponents:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.35)))

    if critical:
        if high_supply and prev_bids:
            target = max(lowest_prev + 2.0, DAILY_SALARY * 1.05)
        else:
            target = max(highest_prev + 1.0, DAILY_SALARY * 1.45)
        return float(min(budget, target))

    if pressured:
        if high_supply and prev_bids:
            target = max(avg_prev * 0.92, lowest_prev + 1.5, DAILY_SALARY * 0.9)
        elif very_tight:
            target = DAILY_SALARY * 0.22
        else:
            target = DAILY_SALARY * 0.75
        if late_game:
            target = max(target, DAILY_SALARY * 0.95)
        return float(min(budget, target))

    if scarcity < 0.45 or very_tight:
        target = DAILY_SALARY * 0.08
    elif high_supply and prev_bids:
        target = min(DAILY_SALARY * 0.85, max(DAILY_SALARY * 0.45, lowest_prev + 1.0))
    else:
        target = DAILY_SALARY * 0.15

    if budget < DAILY_SALARY * 2:
        target = min(target, DAILY_SALARY * 0.12)

    return float(min(budget, max(0.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0
    avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0

    # Determine urgency
    urgent = hp <= 4 or my_status['no_water_days'] >= 2
    # Adjust based on supply scarcity
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)  # 0 to 1

    if urgent:
        # Need water: bid enough to outbid high opponents
        if max_yesterday_bid > DAILY_SALARY * 0.9:
            target_bid = max_yesterday_bid + 5.0
        else:
            target_bid = DAILY_SALARY * 0.8 + scarcity * 30
        return min(budget, target_bid)
    else:
        # Conservative: bid low to save budget, but still try to get water cheaply
        if avg_yesterday_bid > DAILY_SALARY * 0.8:
            # Opponents are aggressive, avoid overpaying
            target_bid = min(DAILY_SALARY * 0.3, DAILY_SALARY * 0.5 - scarcity * 10)
        else:
            target_bid = DAILY_SALARY * 0.5
        return min(budget, max(0, target_bid))
